mapper.select:
SELECT ov.id, ov.course_id AS courseId, ov.version_name AS versionName, ov.semester, ov.status, ov.archive_state AS archiveState, ov.archived_at AS archivedAt, ov.note, ov.updated_by AS updatedBy, ov.updated_at AS updatedAt, ov.completion_percent AS completionPercent, ov.completion_issue_count AS completionIssueCount, ov.completion_state AS completionState FROM outline_version ov WHERE ov.deleted = 0 AND ov.course_id = #{courseId}
AND ov.semester = #{request.semester}
AND ov.status = #{request.versionStatus}
AND ov.completion_state = #{request.completionState}
AND ov.archive_state = #{request.archiveState}
AND LOWER(CONCAT(ov.version_name, ' ', ov.note, ' ', ov.updated_by)) LIKE CONCAT('%', LOWER(#{keyword}), '%')
ORDER BY ov.updated_at DESC, ov.id DESC
